          </Badge>
        ),
      }),
    ],
    [columnHelper, getDirection],
  )

  const filtered = useMemo(
    () => (filter === "all" ? transactions : transactions.filter((tx) => tx.status === filter)),
    [transactions, filter],
  )

  const table = useReactTable({
    data: filtered,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
  })

  const fetchTransactions = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const res = await fetchTransactionsAction(user.id);
      if (!res.ok) throw new Error(res.error ?? `HTTP ${res.status}`)
      const sorted = (res.data ?? []).sort(
        (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
      )
      setTransactions(sorted)
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load transactions")
      setTransactions([])
    } finally {
      setLoading(false)
    }
  }, [user.id])

  const fetchAccounts = useCallback(async () => {
    try {
      const res = await fetch(`/api/wallet/users/${user.id}/accounts`)
      if (res.ok) {
        const json: StandardResponse<WalletAccount[]> = await res.json()
        setAccounts(json.data ?? [])
      }
    } catch {
      setAccounts([])
    } finally {
      setAccountsLoaded(true)
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
  }, [fetchAccounts])

  useEffect(() => {
    if (accountsLoaded) fetchTransactions()
  }, [user.id, accountsLoaded])

  const handleSignOut = async () => {
