import { useState, useMemo } from "react"
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "./ui/card"

interface DailyVolume {
  date: string
  volume: number
}

const periods = [
  { label: "Last 7 days", value: "7d" },
  { label: "Last 30 days", value: "30d" },
  { label: "Last 90 days", value: "90d" },
] as const

export default function ChartAreaInteractive({ data }: { data: DailyVolume[] }) {
  const [period, setPeriod] = useState<string>("30d")

  const filtered = useMemo(() => {
    const days = period === "7d" ? 7 : period === "30d" ? 30 : 90
    return data.slice(-days)
  }, [data, period])

  const maxVolume = Math.max(...filtered.map((d) => d.volume), 1)

  const formatDate = (date: string) => {
    const d = new Date(date)
    return d.toLocaleDateString("en-US", { month: "short", day: "numeric" })
  }

  const getLabel = (value: string) => periods.find((p) => p.value === value)?.label ?? ""

  return (
    <Card>
      <CardHeader className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <CardTitle>Transaction Volume</CardTitle>
          <CardDescription>Daily transaction volume for {getLabel(period)}</CardDescription>
        </div>
        <div className="flex items-center gap-1 rounded-lg border border-border p-0.5">
          {periods.map((p) => (
            <button
              key={p.value}
              type="button"
              onClick={() => setPeriod(p.value)}
              className={`rounded-md px-3 py-1.5 text-xs font-medium transition-colors ${
                period === p.value
                  ? "bg-primary text-primary-foreground"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              {p.label}
            </button>
          ))}
        </div>
      </CardHeader>
      <CardContent className="px-2 sm:px-6">
        <div className="flex items-end gap-[2px] h-44 sm:h-56 pt-2">
          {filtered.map((d, i) => {
            const height = (d.volume / maxVolume) * 100
            return (
              <div
                key={d.date}
                className="relative flex-1 group"
              >
                <div
                  className="w-full rounded-t-[3px] bg-primary/70 hover:bg-primary transition-colors cursor-pointer"
                  style={{ height: `${Math.max(height, 1)}%` }}
                >
                  <div className="absolute -top-8 left-1/2 -translate-x-1/2 whitespace-nowrap rounded-md bg-foreground px-2 py-1 text-xs text-background opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none shadow-md">
                    ${d.volume.toLocaleString()}
                  </div>
                </div>
                {(filtered.length <= 14 || i % Math.ceil(filtered.length / 10) === 0 || i === filtered.length - 1) && (
                  <p className="mt-1.5 text-[10px] text-muted-foreground text-center truncate">
                    {formatDate(d.date)}
                  </p>
                )}
              </div>
            )
          })}
        </div>
        {filtered.length === 0 && (
          <div className="flex items-center justify-center h-44 sm:h-56">
            <p className="text-sm text-muted-foreground">No transaction data available</p>
          </div>
        )}
      </CardContent>
    </Card>
  )
}

import { useState, useMemo } from "react"
import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  flexRender,
  createColumnHelper,
  type SortingState,
} from "@tanstack/react-table"
import { Badge } from "./ui/badge"
import { Skeleton } from "./ui/skeleton"
import type { ITransaction } from "@/types"

interface DataTableProps {
  data: ITransaction[]
  userAccountIds: Set<string>
  loading?: boolean
  emptyMessage?: string
}

const formatBalance = (b: number | string) =>
  new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(Number(b))

const formatDate = (iso: string) =>
  new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(iso))

type SortDir = "in" | "out" | "self"

export default function DataTable({ data, userAccountIds, loading, emptyMessage }: DataTableProps) {
  const columnHelper = createColumnHelper<ITransaction>()

  const getDirection = (tx: ITransaction): SortDir => {
    if (tx.senderName === tx.receiverName) return "self"
    if (userAccountIds.has(tx.receiverAccountNumber.toString()) && !userAccountIds.has(tx.senderAccountNumber.toString())) return "in"
    return "out"
  }

  const columns = useMemo(
    () => [
      columnHelper.accessor("createdAt", {
        header: "Date",
        cell: (info) => (
          <span className="text-sm text-muted-foreground whitespace-nowrap">
            {formatDate(info.getValue())}
          </span>
        ),
      }),
      columnHelper.display({
        id: "direction",
        header: "",
        cell: ({ row }) => {
          const dir = getDirection(row.original)
          return (
            <div className="shrink-0 w-8 h-8 rounded-full flex items-center justify-center text-sm font-semibold bg-secondary text-secondary-foreground">
              {dir === "in" ? "\u2190" : dir === "self" ? "\u21C4" : "\u2192"}
            </div>
          )
        },
      }),
      columnHelper.accessor("senderName", {
        header: "Counterparty",
        cell: (info) => {
          const tx = info.row.original
          const dir = getDirection(tx)
          const label = dir === "self" ? "Deposit" : dir === "in" ? `From ${tx.senderName}` : `To ${tx.receiverName}`
          return (
            <div className="min-w-0">
              <p className="text-sm font-medium text-foreground truncate">{label}</p>
            </div>
          )
        },
      }),
      columnHelper.accessor("amount", {
        header: "Amount",
        cell: (info) => {
          const tx = info.row.original
          const dir = getDirection(tx)
          return (
            <span className={`text-sm font-mono font-semibold whitespace-nowrap ${
              dir === "in" ? "text-success" : dir === "out" ? "text-foreground" : "text-foreground"
            }`}>
              {dir === "in" ? "+" : dir === "out" ? "\u2212" : ""}{formatBalance(tx.amount)}
            </span>
          )
        },
      }),
      columnHelper.accessor("status", {
        header: "Status",
        cell: (info) => (
          <Badge
            variant={info.getValue() === "success" ? "default" : info.getValue() === "failed" ? "destructive" : "secondary"}
            className="text-[10px] px-1.5 py-0 whitespace-nowrap"
          >
            {info.getValue()}
          </Badge>
        ),
      }),
    ],
    [userAccountIds],
  )

  const [sorting, setSorting] = useState<SortingState>([{ id: "createdAt", desc: true }])

  const table = useReactTable({
    data,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
  })

  if (loading) {
    return (
      <div className="space-y-3 p-4">
        {Array.from({ length: 5 }).map((_, i) => (
          <Skeleton key={i} className="h-10 w-full rounded-md" />
        ))}
      </div>
    )
  }

  if (data.length === 0) {
    return (
      <div className="py-10 text-center">
        <p className="text-sm text-muted-foreground">{emptyMessage ?? "No transactions yet."}</p>
      </div>
    )
  }

  return (
    <div className="overflow-x-auto">
      <table className="w-full">
        <thead>
          {table.getHeaderGroups().map((hg) => (
            <tr key={hg.id} className="border-b border-border/50">
              {hg.headers.map((header) => (
                <th
                  key={header.id}
                  className="text-left text-xs font-medium text-muted-foreground px-4 py-3 cursor-pointer select-none hover:text-foreground transition-colors"
                  onClick={header.column.getToggleSortingHandler()}
                >
                  <div className="flex items-center gap-1">
                    {flexRender(header.column.columnDef.header, header.getContext())}
                    {{
                      asc: " \u25B2",
                      desc: " \u25BC",
                    }[header.column.getIsSorted() as string] ?? null}
                  </div>
                </th>
              ))}
            </tr>
          ))}
        </thead>
        <tbody>
          {table.getRowModel().rows.map((row) => (
            <tr key={row.id} className="transition-colors hover:bg-surface-hover">
              {row.getVisibleCells().map((cell) => (
                <td key={cell.id} className="px-4 py-3 border-b border-border/30 last:border-0">
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

import { useEffect, useState, useRef, useCallback } from "react"
import { signOut, useSession } from "../lib/auth-client"
import { Card, CardContent } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"

interface Notification {
  id: string
  title: string
  message: string
  type: "info" | "warning" | "error"
  timestamp: string
  read: boolean
}

interface StandardResponse<T> {
  ok: boolean
  status: number
  message: string
  data?: T
  error?: string
}

function statusVariant(status: string): "default" | "secondary" | "destructive" {
  if (status === "connected") return "default"
  if (status === "disconnected") return "destructive"
  return "secondary"
}

function statusLabel(status: string): string {
  if (status === "connected") return "Live"
  if (status === "disconnected") return "Disconnected"
  return "Connecting"
}

export default function NotificationPage() {
  const { data: session } = useSession()
  const user = session!.user
  const [notifications, setNotifications] = useState<Notification[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [connectionStatus, setConnectionStatus] = useState<"connected" | "disconnected" | "connecting">("connecting")
  const eventSourceRef = useRef<EventSource | null>(null)
  const retryCountRef = useRef(0)

  const fetchInitial = useCallback(async () => {
    try {
      setLoading(true)
      const response = await fetch(`/api/notification/users/${user.id}/notifications?limit=50`)
      if (!response.ok) throw new Error(`HTTP ${response.status}`)
      const json: StandardResponse<Notification[]> = await response.json()
      setNotifications(json.data ?? [])
      setError(null)
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load")
      setNotifications([])
    } finally {
      setLoading(false)
    }
  }, [user.id])

  const connectSSE = useCallback(() => {
    if (eventSourceRef.current) {
      eventSourceRef.current.close()
    }

    setConnectionStatus("connecting")
    const es = new EventSource(`/api/notification/users/${user.id}/notifications/stream`)
    eventSourceRef.current = es

    es.onopen = () => {
      setConnectionStatus("connected")
      retryCountRef.current = 0
    }

    es.onmessage = (event) => {
      try {
        const parsed = JSON.parse(event.data)
        const items: Notification[] = parsed.result ?? parsed.data ?? []
        if (items.length > 0) {
          setNotifications((prev) => {
            const existing = new Set(prev.map((n) => n.id))
            const newItems = items.filter((n) => !existing.has(n.id))
            return [...newItems, ...prev].slice(0, 50)
          })
        }
      } catch {
        // ping or parse error - ignore
      }
    }

    es.onerror = () => {
      setConnectionStatus("disconnected")
      es.close()
      eventSourceRef.current = null

      const delay = Math.min(1000 * 2 ** retryCountRef.current, 30000)
      retryCountRef.current += 1
      setTimeout(connectSSE, delay)
    }
  }, [user.id])

  useEffect(() => {
    fetchInitial()
    connectSSE()
    return () => {
      if (eventSourceRef.current) eventSourceRef.current.close()
    }
  }, [fetchInitial, connectSSE])

  const dismissNotification = (id: string) => {
    setNotifications((prev) => prev.filter((n) => n.id !== id))
  }

  const markRead = (id: string) => {
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, read: true } : n))
    )
  }

  const handleSignOut = async () => {
    await signOut()
  }

  return (
    <>
      <header className="flex items-center justify-between flex-wrap gap-3 px-8 py-5 border-b border-border">
        <h1 className="text-xl font-semibold tracking-tight text-foreground">Notifications</h1>
        <div className="flex items-center gap-3">
          <Badge variant={statusVariant(connectionStatus)}>
            <span className={`mr-1.5 h-1.5 w-1.5 rounded-full inline-block ${
              connectionStatus === "connected" ? "bg-current" :
              connectionStatus === "disconnected" ? "bg-current" :
              "bg-current animate-a-spin"
            }`} />
            {statusLabel(connectionStatus)}
          </Badge>
          <span className="text-sm text-muted-foreground">{user.email}</span>
          <Button variant="outline" size="sm" onClick={fetchInitial}>
            Refresh
          </Button>
          <Button variant="ghost" size="sm" onClick={handleSignOut}>
            Sign Out
          </Button>
        </div>
      </header>

      <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-6">
        {loading && (
          <div className="flex flex-col gap-2">
            {Array.from({ length: 4 }).map((_, i) => (
              <Skeleton key={i} data-testid="skeleton-card" className="h-20 w-full rounded-lg" />
            ))}
          </div>
        )}

        {error && !loading && (
          <div className="flex flex-col items-center justify-center gap-4 py-16 text-center">
            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-destructive/10 border-2 border-destructive/30 text-destructive text-lg font-bold">
              !
            </div>
            <p className="text-muted-foreground">{error}</p>
            <Button variant="outline" onClick={fetchInitial}>
              Retry
            </Button>
          </div>
        )}

        {!loading && !error && notifications.length === 0 && (
          <div className="flex flex-col items-center justify-center gap-2 py-16 text-center">
            <h2 className="text-base font-semibold text-muted-foreground">No notifications</h2>
            <p className="text-sm text-muted-foreground/60">
              New notifications will appear here in real time.
            </p>
          </div>
        )}

        {!loading && !error && notifications.length > 0 && (
          <div className="flex flex-col gap-2">
            {notifications.map((n) => (
              <div
                key={n.id}
                data-testid="notification-card"
                data-read={n.read}
                className={`group rounded-xl px-4 py-3.5 transition-colors ${
                  n.read
                    ? "bg-surface opacity-70 hover:opacity-100"
                    : "bg-accent-subtle"
                }`}
              >
                <div className="flex gap-3">
                  <span
                    className={`mt-1.5 h-2 w-2 shrink-0 rounded-full ${
                      n.type === "info" ? "bg-primary" :
                      n.type === "warning" ? "bg-warning" :
                      "bg-error"
                    }`}
                  />
                  <div className="flex-1 min-w-0">
                    <div className="flex justify-between items-start gap-4 mb-0.5">
                      <h3 className={`text-sm ${n.read ? "font-medium" : "font-semibold"} text-foreground`}>
                        {n.title}
                      </h3>
                      <time className="shrink-0 text-xs text-muted-foreground/70 font-mono">
                        {new Date(n.timestamp).toLocaleTimeString(undefined, {
                          hour: "2-digit",
                          minute: "2-digit",
                        })}
                      </time>
                    </div>
                    <p className="text-sm text-muted-foreground leading-relaxed line-clamp-2">
                      {n.message}
                    </p>
                    <div className="flex gap-2 mt-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      {!n.read && (
                        <Button variant="ghost" size="xs" onClick={() => markRead(n.id)}>
                          Mark read
                        </Button>
                      )}
                      <Button variant="ghost" size="xs" onClick={() => dismissNotification(n.id)}>
                        Dismiss
                      </Button>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </main>

      <footer className="flex justify-between items-center px-8 py-4 text-sm text-muted-foreground/70 border-t border-border">
        <span>Wave Notification Center</span>
        <span>{notifications.length} notifications</span>
      </footer>
    </>
  )
}

